import math
from typing import Tuple

def archimedean_spiral_point(b: float, tx: float, ty: float) -> Tuple[float, float]:
    def spiral_point(phi: float) -> Tuple[float, float]:
        r = b * phi
        return r * math.cos(phi), r * math.sin(phi)

    def line_intersection(p1: Tuple[float, float], p2: Tuple[float, float], q1: Tuple[float, float], q2: Tuple[float, float]) -> bool:
        def orientation(p: Tuple[float, float], q: Tuple[float, float], r: Tuple[float, float]) -> int:
            val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
            if val == 0:
                return 0
            return 1 if val > 0 else 2

        o1 = orientation(p1, p2, q1)
        o2 = orientation(p1, p2, q2)
        o3 = orientation(q1, q2, p1)
        o4 = orientation(q1, q2, p2)

        if o1 != o2 and o3 != o4:
            return True

        if o1 == 0 and is_on_segment(p1, q1, p2):
            return True
        if o2 == 0 and is_on_segment(p1, q2, p2):
            return True
        if o3 == 0 and is_on_segment(q1, p1, q2):
            return True
        if o4 == 0 and is_on_segment(q1, p2, q2):
            return True

        return False

    def is_on_segment(p: Tuple[float, float], q: Tuple[float, float], r: Tuple[float, float]) -> bool:
        return (q[0] <= max(p[0], r[0]) and q[0] >= min(p[0], r[0]) and
                q[1] <= max(p[1], r[1]) and q[1] >= min(p[1], r[1]))

    def check_phi(phi: float) -> bool:
        px, py = spiral_point(phi)
        vx, vy = -py, px
        for i in range(1, 1000):
            pphi = phi + i * 2 * math.pi
            sx, sy = spiral_point(pphi)
            if line_intersection((px, py), (tx, ty), (px, py), (sx, sy)):
                return False
        return True

    low, high = 0, 1000
    while high - low > 1e-6:
        mid = (low + high) / 2
        if check_phi(mid):
            high = mid
        else:
            low = mid

    px, py = spiral_point(low)
    return px, py

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    b = float(data[0])
    tx = float(data[1])
    ty = float(data[2])
    result = archimedean_spiral_point(b, tx, ty)
    print(f"{result[0]:.10f} {result[1]:.10f}")
